// ZAFIYET 3: CSRF Fix
const csrf = require('csurf');
function fixedTransfer(req, res) {
    if (!req.csrfToken || req.body._csrf !== req.csrfToken()) {
        return res.status(403).json({ error: 'Invalid CSRF token' });
    }
    const { to, amount } = req.body;
    transferMoney(req.user.id, to, amount);
    res.json({ success: true });
}

// ZAFIYET 4: DOM XSS Fix
function fixedRedirect() {
    const hash = window.location.hash.substring(1);
    document.getElementById('content').textContent = hash;
}

// ZAFIYET 5: Security Headers Fix
const helmet = require('helmet');
function fixedHeaders(req, res, next) {
    res.setHeader('Content-Security-Policy', "default-src 'self'");
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-XSS-Protection', '1; mode=block');
    res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
    next();
}

